import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { ObjectLink } from "@/components/ui/object-link"

/**
 * Who should act. The AI suggests a team and the person on shift; a person confirms with Assign.
 */
export interface OwnerRowProps {
  team: string
  teamHref: string
  person: string
  personHref: string
  state?: "suggested" | "assigning" | "assigned"
  onAssign?: () => void
  onUndo?: () => void
  className?: string
}

export function OwnerRow({ team, teamHref, person, personHref, state = "suggested", onAssign, onUndo, className }: OwnerRowProps) {
  return (
    <div data-slot="owner-row" data-state={state} className={cn("flex flex-wrap items-center gap-x-2.5 gap-y-2 text-[13px]", className)}>
      <span className="font-mono text-[11px] uppercase tracking-[0.05em] text-muted-foreground">Owner</span>
      <ObjectLink href={teamHref}>{team}</ObjectLink>
      <span className="text-muted-foreground">on shift</span>
      <ObjectLink href={personHref}>{person}</ObjectLink>
      <span className="ml-auto">
        {state === "assigned" ? (
          <span className="inline-flex items-center gap-2 text-muted-foreground">
            Assigned
            {onUndo && <button type="button" onClick={onUndo} className="underline underline-offset-[3px] hover:text-foreground">Undo</button>}
          </span>
        ) : (
          <Button size="sm" variant="secondary" loading={state === "assigning"} onClick={onAssign}>{state === "assigning" ? "Assigning…" : "Assign"}</Button>
        )}
      </span>
    </div>
  )
}
